imgbrowse_copy_explain: "A cópia é uma imagem totalmente nova do mesmo tipo, gravada ao lado da original com -edited no nome, depois relida e verificada. Leva mais ou menos o mesmo tempo que converter o jogo. A original não é alterada.",
imgbrowse_write_copy: "Gravar cópia editada",
