imgbrowse_writing_copy: "Gravando uma cópia editada de {name}",
imgbrowse_copy_done: "Cópia editada gravada e verificada",
imgbrowse_open_copy: "Ver o conteúdo da cópia",
localimage_explain: "Abre a imagem como uma unidade comum neste computador, para que você possa adicionar, substituir e excluir arquivos dentro dela — patches, por exemplo — usando o Finder ou o Explorador, exatamente como em um pendrive. As alterações são salvas diretamente no arquivo de imagem. O ps5upload nunca grava na imagem; quem faz isso é o seu sistema operacional. Ejete-a aqui quando terminar.",
