"pkglib.installAll.what": "O que é “Instalar tudo”?",
"pkglib.installAll.whatBody": "“Instalar tudo” executa todos os pacotes prontos em ordem: jogo base → atualizações → DLC. Quando você tem duas atualizações da mesma versão (ou dois DLCs em conflito), use a caixa de seleção em cada linha para escolher qual este console deve instalar — apenas um por grupo. Desmarque para deixar esse grupo de fora. O botão Instalar de uma linha sempre instala apenas aquele pacote.",
