"fpkg.lowSpace": "Pouco espaço livre: a conversão pode precisar de até {need} na unidade de saída, que tem {free}.",
"fpkg.about": "Aponte para uma pasta de jogo, ou para uma imagem de montagem .exfat ou .ffpkg. O conversor lê a árvore, verifica se está tudo o que um pacote inicializável precisa e grava um .pkg em formato debug na pasta de saída.",
"fpkg.aboutWhere": "A conversão roda na máquina que hospeda o motor — este computador, um host Docker ou um dispositivo Android — e não no console. Nada chega ao console até você instalar o pacote — por stream deste computador, ou enviado antes para o PS5.",
"fpkg.aboutSource": "A origem precisa ser uma árvore de jogo já descriptografada. Uma instalação retail não pode ser extraída aqui, e a verificação abaixo avisa se foi isso que você escolheu.",
"fpkg.aboutChecks": "O que a verificação procura",
"fpkg.checkEboot": "Um eboot.bin na raiz da árvore — o módulo do título. Precisa ser um ELF bruto ou um SELF encapsulado; um módulo assinado para retail não pode ser reempacotado.",
"fpkg.checkParam": "sce_sys/param.json, e nenhum sce_sys/param.sfo — um param.sfo manda o caminho de inicialização do console pela rota do PS4.",
"fpkg.checkIcons": "Um ID de conteúdo de 36 caracteres, os dois ícones e o módulo de direitos sce_sys/about/right.sprx.",
"fpkg.checkDrm": "Que o valor de DRM do pacote seja o padrão. Um valor gratuito ou atualizável faz o console bloquear o título; ele é reescrito só no pacote, e o seu arquivo nunca é alterado.",
"payloads_essentials_title": "Recomendados junto com o ps5upload",
"payloads_essentials_body": "Se você está configurando um console pela primeira vez, estes três cobrem quase tudo o que o ps5upload espera encontrar: kstuff-lite (patches de kernel dos quais a maior parte do homebrew depende), ShadowMount+ (monta imagens de jogos a partir do armazenamento) e nanoDNS (mantém o console fora do caminho de atualização da Sony). Todo o resto da lista é opcional.",
"navigation_history": "Ver histórico",
"navigation_back": "Voltar",
"navigation_forward": "Avançar",
"power_wake_setup_cta": "Configurar despertar e login",
