"power_wake_working": "Configurando este console…",
"power_wake_working_detail": "Ativando a Reprodução Remota, lendo sua conta no console e registrando. Você não precisa fazer nada.",
"power_wake_needs_awake": "Ligue o console para configurar — o pareamento é registrado pela rede, então só funciona com o console acordado. Basta fazer isso uma vez.",
