"library_mount_modal_rw_title": "Leitura e gravação — você pode editar esta imagem",
"library_mount_modal_rw_body": "Montada assim, você pode substituir arquivos, adicionar DLC ou aplicar um patch de backport — use o Navegador de arquivos para editar a montagem. As alterações são gravadas direto no arquivo de imagem: uma edição errada pode deixar o jogo sem iniciar e não dá para desfazer, então copie a imagem antes se ela for importante. O PS5 também pode gravar salvamentos por conta própria em uma imagem montada.",
