"install.library.title": "Cópias de pacotes no PS5",
"install.stream.file.help": "Escolha um .pkg ou .fpkg, ou solte um em qualquer lugar desta janela. Mantenha o app aberto até a instalação terminar; o progresso aparece na fila acima e em Tarefas.",
"install.stream.file.title": "Instalar um arquivo de pacote",
"install.tab.stream.lead": "O PS5 instala direto deste computador ou de um link. Nenhuma cópia é colocada antes no PS5, então não é preciso espaço livre lá, e é a forma mais confiável de instalar.",
"install.tab.upload.lead": "O pacote é copiado primeiro para o PS5 e depois instalado a partir dessa cópia. Use quando o PS5 não consegue alcançar este computador (Transmitir falha com erro de rede), ou para manter pacotes no PS5 e reinstalá-los depois sem este computador.",
"install.upload.file.browser": "Copiar um pacote para o PS5 daqui exige o app de desktop. Na interface web, use Transmitir e instalar, ou instale abaixo os pacotes que já estão no PS5.",
"install.upload.file.help": "Escolha um .pkg ou .fpkg. A cópia precisa de espaço livre no PS5 para o pacote inteiro e fica na lista abaixo até você removê-la.",
"install.upload.file.title": "Copiar um pacote para o PS5 e instalá-lo",
"linkcard.confirm.direct": "O PS5 baixa o pacote do link por conta própria e o instala. Este computador não é mais necessário depois que começa, e o progresso aparece no PS5 (Downloads), não aqui. Se o PS5 não conseguir obter o link, o app o transmite por este computador. Reinstalar por cima de um jogo instalado pode removê-lo se o instalador da Sony falhar. Use apenas links de pacotes em que você confia e que tem autorização para instalar.",
"linkcard.confirm.download": "Este computador primeiro salva o pacote inteiro no disco e depois o instala no PS5. Ele precisa ficar ligado até as duas etapas terminarem e precisa de espaço livre para o pacote. Reinstalar por cima de um jogo instalado pode removê-lo se o instalador da Sony falhar. Use apenas links de pacotes em que você confia e que tem autorização para instalar.",
"linkcard.confirm.stream": "Este computador baixa o pacote e o repassa direto ao PS5, então precisa ficar ligado e conectado até a instalação terminar. Nada é salvo em disco. Reinstalar por cima de um jogo instalado pode removê-lo se o instalador da Sony falhar. Use apenas links de pacotes em que você confia e que tem autorização para instalar.",
"linkcard.confirm.title": "Instalar a partir deste link?",
"linkcard.fact.awake": "Mantenha este computador ligado",
"linkcard.fact.can_close": "Você pode fechar o app",
"linkcard.fact.disk": "Precisa de espaço em disco aqui",
