"linkcard.fact.progress_here": "Progresso mostrado aqui",
"linkcard.fact.progress_ps5": "Progresso no PS5",
"linkcard.forget": "Remover da lista",
"linkcard.help2": "Cole um link de download direto para um .pkg. Nada é copiado para o PS5 antes, então só precisa de espaço para o jogo instalado, não também para uma cópia.",
"linkcard.how": "Como ele deve ser obtido?",
"linkcard.insecure": "Ignorar a verificação do certificado",
"linkcard.insecure_hint": "Para o seu próprio servidor ou um site com certificado vencido. Vale aqui porque é este computador que faz a conexão.",
"linkcard.install": "Instalar a partir do link",
"linkcard.mode.direct": "O PS5 baixa",
"linkcard.mode.direct_body": "O PS5 obtém o link por conta própria. Ele precisa conseguir alcançar o link, e o endereço precisa ser curto (o app encurta um endereço longo e então precisa ficar aberto).",
"linkcard.mode.download": "Baixar aqui primeiro, depois instalar",
"linkcard.mode.download_body": "Este computador salva o pacote inteiro e depois o instala. É o mais lento, mas um link que expira ou cai no meio só custa tentar o download de novo.",
"linkcard.mode.stream": "Transmitir por este computador",
"linkcard.mode.stream_body": "Este computador baixa por várias conexões e repassa direto ao PS5. Geralmente é o mais rápido e funciona quando só este computador alcança o link.",
"linkcard.name": "Nome (opcional)",
