health_junk_explain_v2: "Coisas que o ps5upload criou e não precisa mais: arquivos incompletos de transferências interrompidas, cópias de pacotes deixadas há mais de uma hora na pasta temporária e arquivos antigos de teste de velocidade. Só as pastas do próprio ps5upload são examinadas; seus jogos, pacotes e saves nunca são tocados.",
