stop: "Parar",
activity_description_v2: "Tudo o que o app está fazendo e já fez nos seus consoles: envios, downloads, instalações e operações com arquivos. Pare ou repita uma daqui. As últimas 100 são mantidas, mesmo depois de reiniciar.",
health_subtitle_v2: "Verifica se o PS5, este app e a rede entre eles estão funcionando, diz o que corrigir quando algo não está e mede a velocidade com que os arquivos trafegam entre eles.",
remotePlay_subtitle_v2: "Configure este PS5 para a Reprodução Remota e obtenha o PIN que pareia o app PS Remote Play com ele.",
saves_description_v2: "Dados salvos no PS5, uma entrada por jogo. Faça backup dos saves de um jogo em um .zip neste computador e restaure-os depois.",
shell_description_v2: "Digite comandos que rodam no PS5, no processo do auxiliar. Para uso avançado. A saída é limitada a 256 KB por comando; as setas para cima e para baixo trazem os comandos anteriores.",
