connection_payload_engine_unreachable: "O app não conseguiu falar com o próprio engine neste computador, então não sabe se o auxiliar iniciou no PS5. Não é um problema do PS5: o aviso no topo da janela diz o motivo e pode reiniciar o engine. Depois toque em Enviar auxiliar de novo. ({error})",
"engine_problem.missing.fix": "Restaure o ps5upload-engine da quarentena do antivírus (ou permita-o), ou reinstale o app.",
"engine_problem.missing.why": "O programa do engine sumiu da pasta do app. Softwares de segurança às vezes o colocam em quarentena.",
"engine_problem.port.fix": "Toque em Reiniciar engine. Se não resolver, permita o ps5upload-engine no firewall ou antivírus e reinicie o app.",
"engine_problem.port.why": "Algo ocupa o endereço do engine ({url}) mas não responde: outro programa nessa porta, ou software de segurança bloqueando conexões a ele.",
"engine_problem.proxy.fix": "Desative o proxy ou a ferramenta de VPN para endereços locais (127.0.0.1), ou abra o app sem a configuração http_proxy / ALL_PROXY.",
"engine_problem.proxy.why": "As requisições ao engine foram para um proxy configurado neste computador em vez do engine.",
"engine_problem.remote.fix": "Verifique se o engine (contêiner Docker ou outro computador) está rodando e acessível nesse endereço, ou altere-o em Configurações.",
"engine_problem.remote.why": "O engine que este app está configurado para usar ({url}) não responde.",
"engine_problem.restart": "Reiniciar engine",
"engine_problem.slow.fix": "Toque em Reiniciar engine. Firewall ou antivírus que filtram conexões locais também podem causar isso: permita o ps5upload-engine.",
"engine_problem.slow.why": "O engine está rodando, mas não responde.",
"engine_problem.stopped.fix": "Toque em Reiniciar engine. Se ele parar de novo, a tela Logs mostra o motivo.",
"engine_problem.stopped.why": "O engine não está rodando: ele parou ou nunca iniciou.",
"engine_problem.title": "O app não consegue falar com o próprio engine neste computador",
"engine_problem.phone.title": "O app não consegue acessar o motor",
"engine_problem.phone.why": "O motor roda dentro deste app e parou de responder.",
"engine_problem.phone.fix": "Feche o app por completo e abra de novo.",
"engine_problem.web.fix": "Verifique se o servidor (contêiner Docker) está rodando e recarregue esta página.",
"engine_problem.web.why": "Esta página perdeu a conexão com o servidor do ps5upload de onde veio.",
gate_engine_down_body_v2: "Esta tela precisa do engine do app, que não está respondendo. O aviso no topo da janela diz o motivo e pode reiniciá-lo.",
"profile.np.body": "Faz o PS5 tratar a conta conectada como conectada à PlayStation Network, sem contatar a Sony. Alguns recursos do console só abrem para uma conta conectada, entre eles a Reprodução Remota. Usa o np-fake-signin de earthonion, baixado da página do projeto quando você toca no botão.",
"profile.np.confirm_title": "Conectar esta conta?",
"profile.np.failed": "O login não foi executado",
"profile.np.fetching": "Obtendo o np-fake-signin…",
"profile.np.sending": "Enviando ao PS5…",
"profile.np.sent": "O np-fake-signin {version} rodou no PS5. Reinicie o PS5 para concluir; a conta passa a aparecer conectada, e Configurações > Sistema > Reprodução Remota pode ser ativada.",
"profile.np.sign_in": "Conectar",
"profile.np.state_loading": "Lendo a conta…",
"profile.np.state_no_slot": "Nenhuma conta acima se chama {user}, então o np-fake-signin pararia. Dê à conta o mesmo nome do usuário conectado, ou ative uma para ele.",
"profile.np.state_no_user": "Nenhum usuário está conectado no PS5. Entre no perfil desejado e volte.",
"profile.np.state_not_activated": "{user} (conta {slot}) ainda não tem ID de conta. Ative-a primeiro em Contas, acima.",
"profile.np.state_ready": "Pronto: {user} (conta {slot}) está ativada.",
"profile.np.step_activate": "A conta precisa de um ID de conta. Uma conta vinculada à PSN já tem; caso contrário, ative-a em Contas, acima (ativação offline).",
"profile.np.step_run": "Toque em Conectar com esse usuário conectado no PS5. Ele roda uma vez e termina.",
"profile.np.title": "Conectar à PlayStation Network (offline)",
"fpkg.image.compress": "Comprimir em um .ffpfsc",
