"fpkg.image.make": "Criar imagem do jogo",
"fpkg.image.make_compressed": "Criar imagem comprimida",
"fpkg.image.compress_body_v2": "Geralmente 40–60% menor, mais lenta de criar e sempre montada como somente leitura. É comprimida enquanto é gravada, então só o arquivo comprimido fica no disco.",
"fpkg.image.resume_note": "Se o app ou o motor parar enquanto uma imagem está sendo criada, criá-la de novo continua de onde parou e depois lê de volta cada byte. Uma imagem com pacotes de recursos LZ4 ou zstd começa do zero.",
"fpkg.save_to": "Salvar em",
"fpkg.save_to_computer": "Este computador",
"fpkg.save_to_ps5": "O PS5, direto (nada fica aqui)",
"fpkg.save_to_ps5_note": "Enviada ao PS5 enquanto é escrita e depois lida de volta lá. Se a conexão cair, continua de onde parou.",
"fpkg.save_to_ps5_unsupported": "Direto para o PS5 funciona com uma imagem .exfat, .ffpkg ou .ffpfs simples, ou um .exfat com pacotes zstd. Salve esta neste computador ou mude a imagem acima.",
"fpkg.image.done_ps5": "Imagem do jogo gravada direto no PS5 e lida de volta lá. O ShadowMount+ vai montá-la.",
"fpkg.save_to_server": "Um servidor, direto (nada fica guardado aqui)",
"fpkg.save_to_server_note": "Gravado no servidor enquanto é feito e lido de volta lá antes de receber o nome. Nada fica guardado neste computador.",
"fpkg.save_to_server_unsupported": "Direto para um servidor funciona com uma imagem .exfat, .ffpkg ou .ffpfs simples, ou um .exfat com pacotes zstd. Salve esta neste computador ou mude a imagem acima.",
