trace_what: "Para uma imagem de jogo LZ4 que carrega do jeito que o jogo joga. Uma versão de medição do ampr_emu registra cada arquivo que o jogo lê enquanto você joga; um perfil criado dessas sessões escolhe tamanhos de bloco, layouts e caches por arquivo em vez de um único palpite. O Convert usa isso ao fazer uma imagem LZ4 deste jogo.",
