settings_group_files_saves: "Arquivos e saves",
settings_group_installs: "Instalações",
settings_schedule_label_placeholder_v2: "Rótulo (ex.: backup dos saves)",
settings_updates_browser_note: "Esta página web é servida pelo motor do ps5upload e é atualizada junto com ele: baixe a nova imagem Docker (ou atualize o motor no seu servidor) e reinicie-o.",
"show_file_list_hint_v2": "Lista os arquivos sendo enviados abaixo da barra de progresso. Desligue se a lista ficar poluída em pastas com milhares de arquivos — você ainda verá o progresso geral, a velocidade e o tempo restante.",
show_file_list_v2: "Mostrar a lista de arquivos durante os envios",
stats_description_v2: "Totais das operações exibidas para este console. O app guarda as últimas {count}, então as mais antigas não são contadas. Calculado a partir do histórico local; nada sai da sua máquina.",
update_idle_v2: "Ainda não verificado. Com as verificações automáticas ativadas, o app procura em segundo plano ao iniciar, no máximo uma vez por dia.",
upload_auto_resume_hint_browser: "Se um envio cair no meio da transferência, ele é retomado de onde parou assim que o auxiliar do PS5 responder de novo, tentando algumas vezes antes de desistir. Esta página não consegue reenviar o auxiliar sozinha: se o PS5 reiniciou, envie-o de novo primeiro. Problemas fatais, como o PS5 ficar sem espaço, continuam parando na hora. Ativado por padrão.",
upload_wake_for_uploads: "Acordar o PS5 para um envio em espera",
upload_picker_from_ps5_hint: "Copiando de outro PS5? Selecione os arquivos no Sistema de arquivos e escolha Enviar para outro console.",
