"minion_lan_label": "Abrir o Minion de outros dispositivos da sua rede",
"minion_lan_hint": "Desligado: só o navegador do próprio PS5 consegue abri-lo. Ligado: um celular, tablet ou computador na mesma rede também pode abri-lo, ou seja, qualquer pessoa nessa rede. Ligue só em casa.",
"minion_open_here": "Abrir aqui",
"minion_remove_note": "Remover desliga o Minion e apaga o que ele guarda no PS5: seus favoritos e pastas recentes de Arquivos, a lista salva de jogos e o log do controle. Compartilhamentos de rede, cheats e backups permanecem; o app do PC também os usa.",
"minion_remove": "Remover o Minion deste PS5…",
"minion_remove_title": "Remover o PS5Upload Minion?",
"minion_remove_confirm": "O ícone da tela inicial e a página somem, e os arquivos dele no PS5 são apagados. O auxiliar o mantém desligado daqui em diante. Você pode ligá-lo de novo aqui a qualquer momento.",
"minion_remove_go": "Remover",
"minion_removed_done": "O Minion foi removido: o ícone e a página sumiram e {n} arquivos dele no PS5 foram apagados. Ele continua desligado, mesmo após o auxiliar reiniciar, até você ligá-lo aqui.",
"fs_dragout_n_items": "{n} itens",
