"fs_drag_hint_move": "Arraste arquivos e pastas para fora da janela para copiá-los para este computador, ou para dentro para copiá-los aqui. Segure Alt (⌥ Option no Mac) ao arrastar para movê-los para uma pasta aqui.",
"fs_drag_hint": "Arraste arquivos e pastas para fora da janela para copiá-los para este computador, ou para dentro para copiá-los aqui.",
"fs_device_empty_folder": "Pastas vazias não são enviadas pelo navegador",
