"game_show_in_files": "Mostrar em Arquivos",
"game_search_files": "Pesquisar nos arquivos deste jogo",
"installed_uninstall_no_copy": "Sua Coleção neste computador não tem uma cópia deste jogo: guarde o pacote dele em algum lugar antes de desinstalar.",
"connection_send_payload_moved": "Quer enviar outro payload (kstuff, etaHEN, qualquer .elf)? Isso fica em Payloads → Enviar payload. Esta tela envia apenas o auxiliar do PS5Upload.",
"connection_send_payload_open": "Abrir Enviar payload",
"upload_elf_title": "Isto é um payload (.elf), não um jogo",
"upload_elf_body": "Enviá-lo apenas copia o arquivo. O ShadowMount+ detecta pastas de jogo (com eboot.bin e sce_sys) e imagens de jogo, nunca um .elf, então ele não aparecerá na tela inicial. Para executá-lo, envie-o ao loader do console. O que deve ser enviado é um app homebrew que venha como imagem .ffpkg ou .exfat, ou como pasta com eboot.bin.",
"netdoctor.hint.below_test": "Este envio está a {speed}, bem abaixo dos {expected} medidos pelo teste de velocidade.",
"netdoctor.hint.runs_at": "Este envio está a {speed}.",
"netdoctor.hint.cause_source": "O que o segura é a leitura dos arquivos neste computador, não a rede: um pendrive ou HD, uma pasta de rede (NAS) ou descompactar um arquivo é mais lento que a conexão. Copiar o jogo antes para um SSD interno, ou enviar os arquivos de um compactado já descompactados, dá a velocidade total.",
"netdoctor.hint.cause_disk": "O que o segura é a unidade do PS5, não a rede: um HD USB externo, uma unidade quase cheia ou milhares de arquivos pequenos (cada um custa seu próprio tempo) gravam mais devagar do que a conexão entrega. Uma imagem de jogo (.ffpkg ou .exfat) vai como um único arquivo.",
"netdoctor.hint.cause_workers": "O PS5 ainda está gravando o que recebeu, não está esperando a rede. Com muitos arquivos pequenos cada um custa seu próprio tempo; uma imagem de jogo (.ffpkg ou .exfat) vai como um único arquivo.",
"netdoctor.hint.cause_cap": "O que o segura é o limite de velocidade de envio (cerca de {cap} MiB/s, nesta tela e em Configurações). Defina-o como 0 para removê-lo.",
"profile.np.confirm_body_v2": "O np-fake-signin grava no PS5 os arquivos e configurações de login da PlayStation Network para {user}. Nada é enviado à Sony. Reinicie o PS5 depois.",
"profile.np.side_effect": "Efeito colateral conhecido: depois, alguns consoles pedem para \"Desativar temporariamente as restrições do console PS5\" antes de abrir qualquer jogo, e Configurações > Usuários e contas > Outros > Sair pode ficar acinzentado. O app guarda antes no PS5 uma cópia de tudo o que o np-fake-signin altera, então Desfazer login aqui restaura tudo.",
"profile.np.backing_up": "Guardando no PS5 uma cópia das configurações atuais da conta…",
"profile.np.backup_failed": "O PS5 não conseguiu guardar uma cópia das configurações da conta, então o np-fake-signin não foi executado. Substitua o auxiliar pela versão deste app e tente de novo. ({error})",
"profile.np.step_restart_v2": "Reinicie o PS5. Para desfazer depois, toque em Desfazer login aqui e reinicie de novo.",
"profile.np.undo": "Desfazer login",
"profile.np.undo_hint": "Uma cópia das configurações desta conta de antes do login está guardada no PS5; isto a restaura.",
"profile.np.undo_confirm_title": "Desfazer o login?",
"profile.np.undo_confirm_body": "Devolve as configurações e os arquivos de {user} ao que eram antes do np-fake-signin. Reinicie o PS5 depois. Recursos que precisam de uma conta conectada, como a Reprodução Remota, podem deixar de abrir até você entrar de novo.",
"profile.np.undoing": "Restaurando as configurações…",
"profile.np.undone": "Restaurado ({count} configurações e arquivos). Reinicie o PS5 para concluir.",
"profile.np.no_backup": "Esta conta tem as configurações do modelo do np-fake-signin (data de nascimento 1983-04-12, sinal de adulto offline desligado) e não há cópia de antes neste PS5, então o app não consegue desfazer. Se o PS5 agora pede para desativar temporariamente as restrições do console antes de abrir jogos: Configurações > Família e controle dos pais > Restrições do console PS5 (senha 0000, a menos que você tenha mudado), e retire as restrições lá.",
"linkdl.lz4_title": "Este link está compactado com LZ4",
"linkdl.image_title": "Este link é uma imagem de jogo",
"linkdl.lz4_help": "O ps5upload pode descompactá-lo durante o download, então o PS5 recebe o arquivo descompactado. Nada é salvo neste computador, e o PS5 só precisa de espaço para o arquivo descompactado.",
"linkdl.lz4_unpack": "Descompactar no caminho",
"linkdl.lz4_unpack_hint": "Desligado: o arquivo .lz4 é salvo no PS5 como está.",
"linkdl.image_hint": "Uma imagem de jogo {kind}. O ShadowMount+ a monta como está a partir de uma pasta que ele verifica, como homebrew em uma unidade. O arquivo só aparece lá quando estiver completo.",
"pm_add_failed": "Não foi possível guardar {name} no Payload Manager",
"pm_catalogue_match": "Catálogo: {name}",
"pm_replace_tooltip": "O Payload Manager não guarda a versão de um payload adicionado à mão, então o ps5upload não consegue saber se este é mais antigo. Substituir guarda a versão do catálogo no lugar dele, mantendo sua posição na lista de inicialização; depois disso, as atualizações são oferecidas aqui.",
