"ps4move_badge": "Experimental",
"ps4move_experimental": "Experimental: pôr saves no formato do PS4 em um PS5 nem sempre funciona, e um jogo pode não carregar. Teste primeiro um jogo; o save do PS5 dele fica guardado e pode voltar pelos backups do jogo.",
"ps4move_safety": "O PS4 é só lido, nunca alterado. Os saves dele são copiados primeiro para este computador. No PS5 só os jogos escolhidos são tocados, o save de cada um é guardado antes de ser trocado, e nada mais (usuários, arquivos do sistema, troféus) muda.",
