"fpkg.ps4_game_note_v2": "Um jogo de PS4. Ele é convertido em pacote de PS4, imagem de jogo ou pasta; uma imagem ou pasta recebe o param.json de que o ShadowMount+ precisa.",
"fpkg.ps4_merged_note_v2": "O jogo de PS4 {title} com a atualização integrada: {from} passa a ser {to}. Ele é convertido em pacote de PS4, imagem de jogo ou pasta nessa versão.",
"fpkg.ps4_patch_note_v2": "Uma atualização de PS4, versão {version}, para {title}. Ela contém só os arquivos que mudaram, então sozinha não é um jogo: escolha abaixo o jogo ao qual ela pertence, e o que você criar será o jogo nesta versão.",
"fpkg.ps4_pkg.options": "Um pacote de PS4 mantém os arquivos do jogo como estão: nada é comprimido, o jogo mantém todos os seus idiomas e cada arquivo é lido de volta e comparado antes de o pacote ser mantido.",
"fpkg.ps4_licence_note": "Um complemento de PS4 para {title} que é só uma licença: ele desbloqueia algo no jogo e não tem arquivos, então não há nada para converter.",
"fpkg.ps4_addon_note": "Um complemento de PS4 para {title}. Os arquivos dele viram uma pasta, não uma imagem nem um pacote. O ShadowMount+ não monta complementos: eles chegam ao jogo só onde o próprio jogo os procura, como uma pasta dentro do jogo.",
"fpkg.merge.title_patch": "Integrar ao jogo",
"fpkg.merge.title_game": "Integrar uma atualização ao jogo (opcional)",
"fpkg.merge.game_label": "O jogo ao qual esta atualização pertence",
"fpkg.merge.update_label": "Uma atualização de PS4 para este jogo",
"fpkg.merge.hint": "Um pacote, imagem ou pasta. A atualização precisa ser do mesmo título e mais nova que o jogo.",
"fpkg.merge.browse": "Procurar",
"fpkg.merge.ok": "✓ {title}: {from} passa a ser {to}. A atualização substitui {replaced} arquivos e adiciona {added}.",
"fpkg.merge.pick_game": "Escolha o jogo de PS4 ao qual esta atualização pertence",
"fpkg.merge.pick_update": "Escolha uma atualização de PS4 para este jogo",
"fpkg.image.zstd": "Pacotes de recursos zstd (menores, para ShadowMount+)",
"fpkg.image.zstd_body": "Empacota tudo, exceto os arquivos de sistema do jogo, em pacotes zstd, gravados direto na imagem sem cópia temporária. A imagem recebe o ampr-emu-ng do quer3q como emulador, conferido com um digest publicado antes de ser usado. Um jogo já em pacotes LZ4 é convertido. Desative update_emulators no ShadowMount+, ou ele pode trocar o emulador por um que não os lê.",
"fpkg.image.zstd_level": "Nível de compressão",
"fpkg.image.zstd_runtime": "Runtime dos pacotes",
"fpkg.image.zstd_runtime_latest": "Versão mais recente (padrão)",
"fpkg.image.zstd_runtime_pinned": "Testada {version}",
"fpkg.image.zstd_runtime_body": "“Mais recente” usa a última versão do ampr-emu-ng no GitHub somente se ela bater com o SHA-256 que o GitHub publica para ela; caso contrário, ou offline, entra a testada {version}. “Testada” usa sempre {version}.",
"fpkg.folder.zstd_body": "Grava o jogo como uma pasta comum, com tudo exceto os arquivos de sistema em pacotes zstd e o ampr-emu-ng do quer3q como fakelib/libSceAmpr.sprx. Uma pasta de jogo também pode ser a origem. Pacotes LZ4 não são oferecidos aqui: vão apenas em uma imagem .exfat. Desative update_emulators no ShadowMount+, ou ele pode trocar o emulador por um que não os lê.",
"ampr_emu_add_hint": "Este jogo lê seus arquivos pelo AMPR e não tem emulador. Alguns jogos assim não iniciam de uma imagem sem ele, e outros funcionam bem. Adiciona o ampr_emu 0.4.2.1 do drakmor, baixado uma vez e conferido com um resumo conhecido. A imagem não é alterada: o emulador vai para uma pasta de backport do ShadowMount+.",
"ampr_emu_done_backport": "Adicionado como backport do ShadowMount+ em {folder}. A imagem não foi alterada. Inicie o jogo para testar.",
"ampr_emu_done_folder": "Adicionado à pasta do jogo, {folder}. Inicie o jogo para testar.",
"fpkg.fake_sign_note": "{count} executáveis simples (sem assinatura) deste jogo recebem assinatura falsa na conversão, senão ele não iniciaria. A origem não é alterada.",
"fpkg.image.ampr_emu": "Adicionar o emulador AMPR",
"fpkg.image.ampr_emu_body": "Este jogo lê seus arquivos pelo AMPR e não tem emulador. Alguns jogos assim não iniciam de uma imagem sem ele, e outros funcionam bem. Adiciona o ampr_emu 0.4.2.1 do drakmor como fakelib/libSceAmpr.sprx, baixado uma vez da versão no GitHub e conferido com um resumo conhecido.",
"fpkg.image.lz4_placement_note": "Mantenha uma imagem compactada no armazenamento interno do console: há relato de uma que travou em tela preta pelo USB. Desative update_emulators no ShadowMount+, ou ele pode trocar o emulador por um que não lê pacotes.",
