"rpg_user_title": "Entre com um usuário no PS5",
"rpg_user_body": "No console, escolha o usuário com que você vai jogar. Ninguém precisa ficar na frente da tela, mas o usuário precisa estar conectado. Se o usuário tiver senha de acesso, Jogar pede a senha quando você pressiona Iniciar.",
