"rp_keys_body3": "Clique na imagem para jogar com o teclado; Esc devolve o ponteiro. Clique duplo para tela cheia; lá, Esc rápido é Círculo e segurar Esc sai da tela cheia. Teclas, som e mais em Configurações.",
