"dump_decrypt_risk": "Descriptografar pode travar o console",
"dump_decrypt_risk_body": "Para descriptografar, o auxiliar troca brevemente, para cada executável, uma parte do sistema que todo programa usa. Se o jogo ler um arquivo nesse momento, o console pode travar e precisar ser desligado à força. Fique na tela inicial do jogo enquanto isso. Só firmware até 13.60; em firmware mais novo o dump é uma cópia simples.",
