"notif_ps5_hint": "Mensagens que o ps5upload exibiu na tela do seu PS5 (um PIN da Reprodução Remota, um truque ativado), lidas do auxiliar dele a cada 5 segundos. Não é o painel de notificações do próprio PS5.",
