"rp_picture_here": "Imagem neste dispositivo",
"rp_picture_here_hint": "Desligado, novas transmissões começam aqui sem imagem, som nem controle, o que economiza CPU e bateria deste dispositivo. Os amigos no Play Together e o Go live continuam recebendo a transmissão, e você pode ligar pela própria transmissão a qualquer momento.",
"rp_picture_off_title": "A imagem está desligada neste dispositivo",
"rp_picture_off_body": "A transmissão continua para seus amigos e sua live. Aqui também não há som nem controle, então este dispositivo quase não tem trabalho.",
"rp_picture_turn_on": "Ligar a imagem",
"rp_picture_turn_off": "Desligar a imagem neste dispositivo",
"golive_picture_hint": "Desligado, este computador repassa a transmissão sem decodificar nem mostrar, o que economiza CPU e calor. Deixe o app aberto; o controle continua aqui.",
"pt_picture_hint": "Desligado, este dispositivo só convida seus amigos: sem imagem, som nem controle aqui, e o jogo deles continua. Para jogar na TV.",
"pt_tv_title": "Vai jogar na TV?",
"pt_tv_note": "Esta transmissão está conectada com o usuário do PS5 que você pareou com o PS5Upload. Aperte PS no DualSense do console e escolha outro usuário: esse é você na TV. Escolher o usuário da transmissão encerra a transmissão para todos, amigos inclusive. Alguns jogos também contam o usuário da transmissão como jogador, o que pode deixar uma vaga a menos para um amigo.",
"pt_tv_seats": "Um PS5 aceita 4 controles. Com seu DualSense na TV, o primeiro amigo usa o controle da própria transmissão e joga como o usuário dela, sem escolher usuário, e mais 2 recebem um controle próprio: espaço para 3 amigos.",
"pt_stream_seat_note": "Um amigo está usando o controle desta transmissão, então seu controle aqui não joga até ele sair.",
"queue_waiting_for_engine_queue": "Aguardando: um script ou agente está usando este PS5 pela fila do mecanismo. Depois, isto continua sozinho.",
