"activity_waiting_count": "{count} aguardando",
"send_title_v2": "Enviar e instalar",
"collection.send_many_body_v2": "Cada PS5 recebe o que falta: o pacote do jogo, ou sua pasta, imagem ou arquivo compactado, além de atualizações e DLC mais novos para os jogos que ele tem. Pacotes são transmitidos deste computador; o resto é enviado para a unidade definida em «Enviar e instalar», na pasta homebrew.",
"first_run_step4_body_v3": "Conecte ao seu PS5 um pendrive com imagens de jogo .ffpkg e o ShadowMount+ vai montá-las automaticamente — elas aparecerão em Jogos. Para enviar outros arquivos ou instalar pacotes .pkg, use «Enviar e instalar».",
"first_run_go_upload_v2": "Abrir Enviar e instalar",
"fpkg.aboutFake_v2": "O resultado é um pacote falso, então o console precisa ter o suporte a pacotes falsos carregado antes de instalá-lo: kstuff (a versão com suporte a pacotes falsos de PS5), a53_ppr_install_fast.elf e shadowmountplus.elf, nessa ordem. «Enviar e instalar» diz o mesmo ao lado dos botões de instalação.",
"fpkg.openUpload_v2": "Abrir Enviar e instalar",
"netdoctor.speed_cap.on.fix_v2": "Remova o limite em «Enviar e instalar» se não precisar dele.",
"payloads_fpkg_ppr_note_v2": "Instalar pacotes falsos também exige a53_ppr_install_fast.elf, que não está nesta lista: não há download publicado e ele é compilado a partir do código-fonte no GitHub. «Enviar e instalar» lista tudo o que os pacotes falsos precisam, em ordem.",
"fs_extract_next_pkgs_v2": "Contém {n} pacote(s): instale-os em «Enviar e instalar» ou pela linha deles aqui.",
"game_hub_no_addons_v2": "Nenhum pacote de DLC preparado para este título. Envie um por «Enviar e instalar».",
"game_hub_open_install_v2": "Abrir Enviar e instalar",
"bandwidth_cap_off_hint_v3": "Sem limite. Defina um se os envios saturarem seu Wi-Fi/LAN e deixarem outros dispositivos lentos. Vale para todo envio, de «Enviar e instalar», da fila e de Arquivos, a partir do próximo.",
"game_hub_no_updates_v2": "Nenhum pacote de atualização preparado para este título. Envie um por «Enviar e instalar».",
"pkglib.fpkgsupport.firmware": "Pacotes falsos de PS5 (PS5 FPKG) ainda não são suportados em firmware posterior ao 11.60: eles instalam, mas o jogo não inicia. Pacotes falsos de PS4 funcionam.",
"upload_drop_here3": "Solte ou escolha pacotes, jogos, imagens de disco, arquivos compactados ou qualquer arquivo",
"upload_pick_here_mobile3": "Escolha pacotes, jogos, imagens de disco, arquivos compactados ou qualquer arquivo",
"upload_drop_kind_pkg": "Pacotes (.pkg, .fpkg): instalados como jogo, atualização ou DLC, transmitidos daqui ou enviados primeiro.",
"upload_drop_kind_game": "Pastas de jogo e dumps de jogos: copiados para o PS5; podem ir para a tela inicial.",
"upload_drop_kind_image": "Imagens de disco (.exfat, .ffpkg, .ffpfs, .ffpfsc): copiadas para o PS5; podem ser montadas.",
"upload_drop_kind_archive": "Arquivos compactados (.zip, .7z, .rar): extraídos no PS5 ou enviados como estão — você escolhe.",
"upload_drop_kind_other": "Qualquer outro arquivo ou pasta: copiado como está.",
"upload_other_ways": "Ou instale um pacote:",
"queue_stream_fail_hint": "«Transmitir e instalar» faz o PS5 buscar o pacote deste computador. Se continuar falhando, permita o ps5upload no firewall deste computador na rede local para que o PS5 consiga alcançá-lo, ou use «Tentar de novo enviando», que copia o pacote para o PS5 primeiro e depois o instala.",
"err_install_enoent_generic_v2": "O instalador da Sony não conseguiu abrir um arquivo necessário durante a instalação (erro de kernel 0x80020002 = ENOENT). Se for um pkg de DLC, o jogo base ainda não está instalado — instale o base primeiro. Caso contrário, o pacote preparado pode ter sido excluído entre o envio e a instalação; tente a instalação mais uma vez. Se continuar falhando, instale-o com «Transmitir e instalar» em «Enviar e instalar», que envia o pacote direto deste computador em vez de copiá-lo antes para o console.",
"err_display_crashed": "A tela do app teve um erro durante isso (React #185) e parou de acompanhar a transferência, que pode ter terminado mesmo assim. Veja o PS5 ou toque em Tentar novamente. Enviar um relatório de bug agora nos ajuda a corrigir.",
"upload_convert_first": "Converter primeiro",
"batch_convert_first_hint": "Abrir os jogos, pastas e imagens marcados na Oficina, para primeiro criar pacotes, imagens ou pastas a partir deles",
"add_sources_pick_folders": "Escolher uma ou mais pastas",
"add_sources_pick_files": "Escolher um ou mais arquivos",
"workshop_add_hint": "Escolha um jogo para verificá-lo aqui. Vários jogos, ou uma pasta de jogos, vão para a fila e são criados um após o outro.",
"cq_title_v2": "⑤ Fila",
"cq_about": "Criados um após o outro neste computador, cada um como ②, ③ e ④ estavam definidos quando foi adicionado. Adicione mais em ①, mesmo com a fila rodando; mude um jogo em espera pelo botão de opções dele.",
"cq_then_send": "Um jogo definido para instalar ou enviar vai para a fila de {send} assim que é criado.",
"cq_open_send": "Abrir {send}",
"backup_alike_toggle": "{count} cópias iguais desde {since}. Mostre cada uma para restaurar uma mais antiga.",
"add_sources_no_picker": "Esta versão não consegue navegar neste computador — digite um caminho que o motor consiga ver.",
"collection.empty_body_v2": "Pacotes, pastas de jogo, imagens de jogo e arquivos compactados dentro dela são encontrados e agrupados por jogo. Nada na pasta é alterado. Serve uma pasta neste dispositivo, uma unidade externa ou uma pasta em um NAS ou servidor (SMB, FTP, SFTP, WebDAV).",
"collection.add_nas_folder": "De um NAS ou servidor",
"browse_this_device": "Este dispositivo…",
"browse_this_device_hint": "Lê do dispositivo em que este navegador está rodando. É copiado duas vezes, para o servidor e depois para o PS5: é mais lento, e o servidor precisa de espaço livre para a cópia.",
"browse_on_server": "No servidor…",
"browse_on_server_hint": "Lê de {host}, o computador em que o motor está rodando. O mais rápido: vai direto para o PS5.",
"browse_choose_source": "Escolha de onde ler",
"queue_added_waits_for_start": "Adicionado à fila — toque em “Iniciar fila” para executar",
"queue_added_waits_for_start_body": "“Iniciar a fila ao adicionar algo” está desativado, então nada começa até você tocar em “Iniciar fila”.",
"queue_auto_start": "Iniciar a fila ao adicionar algo",
"queue_auto_start_tooltip": "Ativado: “Instalar”, “Enviar agora” e “Enviar” iniciam toda a fila deste console, em ordem. Desativado: eles só adicionam à fila, e nada é executado até você tocar em “Iniciar fila”.",
"queue_auto_start_hint": "Ativado: “Instalar”, “Enviar agora” e “Enviar” iniciam toda a fila do console, em ordem — não só o que você acabou de adicionar. Desativado: eles só adicionam à fila, e nada é executado até você tocar em “Iniciar fila”. Ativado por padrão.",
"queue_start_rest_tooltip": "Só os itens que você iniciou estão em execução. Isto executa também tudo o que está esperando, na ordem da fila.",
"queue_start_v2": "Iniciar fila",
"queue_stop_v2": "Parar fila",
"upload_starts_queue": "Inicia a fila: o que já estava esperando vai primeiro, em ordem",
"upload_waits_for_start": "Adiciona à fila. É executado quando você toca em “Iniciar fila” (“Iniciar a fila ao adicionar algo” está desativado)",
