helper_copy_place_pldmgr: "Payload Manager",
helper_copy_place_etahen: "payloads do etaHEN",
helper_copy_place_autoloader: "autoloader",
helper_boot_label: "Carregar o auxiliar do PS5Upload na inicialização",
helper_boot_hint: "O Payload Manager inicia o auxiliar depois de tudo o que vem antes dele na lista de inicialização, então o Minion e este app funcionam após reiniciar sem PC. A cada conexão, este app atualiza essa cópia para o próprio auxiliar e guarda a anterior; se uma cópia nova não iniciar após reiniciar, a anterior volta.",
helper_boot_list_off: "A lista de inicialização do Payload Manager está desligada acima, então nada inicia na inicialização até você ligá-la.",
helper_boot_bad_version: "O auxiliar {version} não iniciou na inicialização deste PS5, então a cópia anterior foi restaurada. Uma versão mais nova do app tentará de novo.",
helper_boot_needs_pm: "Carregar o auxiliar do PS5Upload na inicialização precisa do Payload Manager: é ele que inicia o auxiliar quando o PS5 liga.",
helper_boot_failed: "Não foi possível mudar se o auxiliar carrega na inicialização",
helper_boot_on_title: "O auxiliar agora carrega na inicialização",
helper_boot_restored_title: "O auxiliar não iniciou na inicialização",
helper_boot_restored_body: "O PS5 reiniciou, mas o auxiliar {version} guardado no Payload Manager não iniciou, então este app enviou um. A cópia anterior voltou ao Payload Manager e inicia na próxima reinicialização. Este app não vai guardar {version} lá de novo.",
helper_copies_updated_title: "Auxiliar atualizado",
