mcp_phone_title: "Configure isso em um computador",
mcp_phone_body: "O mecanismo deste app de celular é só para o próprio app. Para usar um agente ou script, execute-os em um computador com o PS5Upload aberto ou com o mecanismo Docker.",
mcp_other_computer_title: "Este mecanismo está em outro computador",
mcp_other_computer_body: "Um agente naquele computador pode seguir estes passos com o próprio endereço 127.0.0.1. Um agente em qualquer outro lugar também precisa ter o endereço na configuração PS5UPLOAD_ALLOW_IP do mecanismo.",
mcp_intro: "O MCP permite que um agente de IA controle seu PS5 com ferramentas que ele entende: enviar arquivos, instalar jogos, ver temperaturas e mais. Adicione uma vez e depois é só pedir.",
mcp_address: "Endereço do MCP",
mcp_agents_title: "Adicione ao seu agente",
mcp_check_again: "Verificar de novo",
mcp_after_adding: "Inicie uma nova sessão no agente para carregar. Mantenha o PS5Upload aberto enquanto o agente trabalha: o servidor MCP faz parte do mecanismo dele.",
mcp_update_title: "Como manter atualizado",
mcp_update_app: "Quando o PS5Upload é atualizado, não há nada a fazer aqui. Os agentes recebem as ferramentas do mecanismo, então as novas aparecem na próxima sessão. Uma sessão já aberta mantém a lista antiga.",
mcp_update_address: "Se o endereço do mecanismo mudar, o app avisa ao iniciar e o cartão do agente mostra Atualizar. Um clique resolve.",
mcp_update_by_hand: "O app não consegue ver Gemini CLI, Cursor, Claude Desktop nem seus scripts. Se o endereço aqui mudar, ou um deles parar de conectar depois de uma atualização, copie a configuração de novo em Outros agentes e apps.",
mcp_update_version: "Este mecanismo é a versão {version}. Para ver a que um agente está conectado, pergunte a ele qual é a versão do mecanismo do PS5Upload.",
mcp_bridge_body: "Ele executa o programa de ponte do mecanismo em vez de usar este endereço. Isso também funciona. Atualizar muda para o endereço.",
mcp_stale_toast: "Um agente ainda tem o endereço antigo do mecanismo e não consegue conectar. Atualize em MCP & API.",
mcp_stale_open: "Abrir",
mcp_try_title: "Depois, tente perguntar",
mcp_try_status: "Qual é a temperatura do meu PS5 agora?",
mcp_try_space: "O que está ocupando mais espaço no meu PS5?",
mcp_try_install: "Instale este pacote no meu PS5 e me avise quando terminar.",
mcp_safety_title: "Um agente pode fazer tudo o que você pode",
mcp_safety_body: "Não há senha, e ele pode apagar arquivos do console. Deixe em \"ask\" as ferramentas que alteram algo e leia cada comando do console antes de permitir.",
mcp_safety_read_only: "Para ele só poder olhar, defina isto no ambiente do mecanismo e reinicie o mecanismo:",
mcp_access_label: "Agentes podem alterar coisas",
