cb_step_restart: "Reinicie e entre no Modo de Segurança de novo",
cb_step_restart_body: "O Modo de Segurança pode abrir mostrando só a última opção, Redefinir PS5 (reinstalar o software do sistema). Segundo relatos, escolher Reiniciar PS5 e entrar no Modo de Segurança outra vez traz as outras opções de volta. Tente isso antes de tudo.",
