cb_step_rebuild: "Limpar cache e reconstruir banco de dados",
cb_step_rebuild_body: "Reconstrói a lista de conteúdo do console. Mantém seus jogos e saves. Em um console com jailbreak, jogos e apps registrados à mão podem precisar ser registrados de novo. Alguns relatam que isso bastou, mas não confirmamos.",
