cb_step_reinstall: "Redefinir PS5 (reinstalar o software do sistema)",
cb_step_reinstall_body: "O último recurso: também remove o software do sistema e exige um arquivo de reinstalação em um pendrive. O site da Sony só oferece a versão mais recente, então usar o arquivo dele atualiza seu firmware e pode acabar com o jailbreak.",
