"auto_bringup_hint_ps5": "Quando o carregador deste PS5 (elfldr, porta 9021) está ativo e o auxiliar não está rodando, o app faz a inicialização rápida sozinho: a playlist de inicialização deste PS5, se você definiu uma, depois o auxiliar, depois sua playlist do carregador automático. Uma vez a cada vez que este PS5 liga; depois do modo de repouso, só o auxiliar é enviado de novo. Ele espera cerca de 90 segundos depois que o carregador aparece, para o carregador automático do próprio console terminar antes. Desativado por padrão.",
