"upload_auto_redeploy_on_wake_hint_ps5": "Quando o auxiliar deste PS5 fica offline (modo de repouso, troca de Wi-Fi ou falha de um payload), continuar tentando enviá-lo de novo em segundo plano, para que o auxiliar, o limite do ventilador deste PS5 e a porta de envio voltem sozinhos assim que ele estiver acessível de novo. Ativado por padrão.",
"keep_ps5_awake_mode_hint_ps5": "Zera o timer de espera automática deste PS5 para ele não entrar em modo de repouso. “Durante envios e instalações” protege envios longos (uma causa comum de envios com falha; padrão). “Sempre enquanto conectado” mantém este PS5 fora do modo de repouso enquanto o auxiliar roda e o app está aberto. Colocar o PS5 em repouso você mesmo funciona em qualquer modo.",
"upload_rest_after_hint_ps5": "Quando a fila de envios deste PS5 terminar, pedir que ele entre em modo de repouso, útil para uma fila durante a noite. Só se pelo menos um envio tiver concluído (não depois de Parar nem se tudo falhou). Desativado por padrão. Alguns firmwares recusam o modo de repouso; você recebe um aviso se este PS5 recusar.",
"upload_wake_for_uploads_hint_ps5": "Quando um envio estiver esperando este PS5 em modo de repouso, mandar um sinal para acordá-lo e continuar assim que o auxiliar voltar. Exige o acordar configurado para este PS5 na tela Conexão. Ativado por padrão.",
"install_path_fallback_hint_ps5": "Um último recurso para um pacote que já está neste PS5, quando ele o recusa do próprio armazenamento e também não consegue buscá-lo deste computador. Só é usado para um jogo base que não está instalado, então não pode remover nada. Não comprovado: funcionou no firmware 11.20 e é recusado no 13.60, por isso é definido para cada PS5. Se você testar, conte se funcionou.",
